pub fn ImageCreateRaw(client: *Client, fromImage: ?[]const u8, fromSrc: ?[]const u8, repo: ?[]const u8, tag: ?[]const u8, message: ?[]const u8, requestBody: []const u8, @"X-Registry-Auth": []const u8, changes: ?[]const std.json.Value, platform: ?[]const u8) !RawResponse {
    const allocator = client.allocator;
    _ = @"X-Registry-Auth";
    var uri_buf: std.Io.Writer.Allocating = .init(allocator);
    defer uri_buf.deinit();
    try uri_buf.writer.print("{s}/images/create", .{client.base_url});
    var first_query = true;
    if (fromImage) |value| {
        try appendQueryParam(&uri_buf.writer, &first_query, "fromImage", value);
    }
    if (fromSrc) |value| {
        try appendQueryParam(&uri_buf.writer, &first_query, "fromSrc", value);
    }
    if (repo) |value| {
        try appendQueryParam(&uri_buf.writer, &first_query, "repo", value);
    }
    if (tag) |value| {
        try appendQueryParam(&uri_buf.writer, &first_query, "tag", value);
    }
    if (message) |value| {
        try appendQueryParam(&uri_buf.writer, &first_query, "message", value);
    }
    if (changes) |value| {
        try appendQueryParam(&uri_buf.writer, &first_query, "changes", value);
    }
    if (platform) |value| {
        try appendQueryParam(&uri_buf.writer, &first_query, "platform", value);
    }
    const payload: ?[]const u8 = requestBody;

    var headers = std.ArrayList(std.http.Header).empty;
    defer headers.deinit(allocator);
    const auth_header = try appendClientHeaders(allocator, &headers, client, "text/plain", "application/json");
    defer if (auth_header) |value| allocator.free(value);

    if (client.http_observer) |obs| {
        if (obs.onRequest) |cb| cb(obs.ctx, std.http.Method.POST, uri_buf.written(), headers.items, payload);
    }

    const uri = try std.Uri.parse(uri_buf.written());
    var response_body: std.Io.Writer.Allocating = .init(allocator);
    defer response_body.deinit();
    const start = std.Io.Clock.awake.now(client.io);
    const result = client.http.fetch(.{
        .location = .{ .uri = uri },
        .method = std.http.Method.POST,
        .extra_headers = headers.items,
        .payload = payload,
        .response_writer = &response_body.writer,
    }) catch |err| {
        if (client.http_observer) |obs| {
            if (obs.onError) |cb| cb(obs.ctx, std.http.Method.POST, uri_buf.written(), @errorName(err));
        }
        return err;
    };
    const elapsed_ns = @as(u64, @intCast(start.untilNow(client.io, .awake).nanoseconds));

    const body = try response_body.toOwnedSlice();

    if (client.http_observer) |obs| {
        if (obs.onResponse) |cb| cb(obs.ctx, std.http.Method.POST, uri_buf.written(), result.status, &.{}, body, elapsed_ns);
    }

    return .{
        .allocator = allocator,
        .status = result.status,
        .body = body,
    };
}

